545→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
546→  // showHeading: pass false when the caller already renders a heading (e.g. popup modal header)
547→  function buildWidgetInner(wid, cfg, btnLabel, showHeading) {
548→    var headingHtml = (showHeading !== false) ? (
549→      '<div class="zcc-heading">' +
550→        '<span class="zcc-heading-icon">' +
551→          '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
552→        '</span>' +
553→        '<span>' + esc(cfg.heading) + '</span>' +
554→      '</div>'
555→    ) : '';
556→    return (
557→      headingHtml +
558→      '<div class="zcc-search-bar">' +
559→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
560→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
561→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
562→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' +
563→          '<span class="zcc-btn-icon">' + ICONS.search + '</span>' +
564→          '<span class="zcc-btn-label">' + esc(btnLabel) + '</span>' +
565→        "</button>" +
566→      "</div>" +
567→      '<div id="' + wid + '-res" aria-live="polite"></div>'
568→    );
569→  }
570→
571→  function wireWidget(wid, cfg, API_BASE, SHOP) {
572→    var inp = document.getElementById(wid + "-inp");
573→    var btn = document.getElementById(wid + "-btn");
574→    var res = document.getElementById(wid + "-res");
575→    if (!inp || !btn || !res) return;
576→
577→    function normalizeZip(raw) {
578→      var z = raw.trim().toUpperCase();
579→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
580→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
581→      return z;
582→    }
583→
584→    // Store the original button HTML so we can restore it exactly after loading
585→    var btnOriginalHtml = btn.innerHTML;
586→
587→    function setBtnLoading(loading) {
588→      btn.disabled = loading;
589→      if (loading) {
